import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import java.util.*;

public final class StarterDeck100EmpoleonTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){live();disabled();exceptions();transfer();System.out.println("StarterDeck100EmpoleonTest passed: opposing Basic non-Rule-Box Active/Bench suppression, live switching/disable restoration, own/evolution/Rule-Box exclusions and mandatory Special Energy transfer");}
    static void live(){var m=StarterDeck100PokemonTest.game(100,171,id(7),id(171));var source=m.activePokemonView(A).pokemonId();check(m.abilityOptions(B).isEmpty(),"Emperor Eyes did not remove both Mew abilities");var own=StarterDeck100PokemonTest.hand(m,id(171));m.playBasicPokemonToBench(A,own.instanceId());check(m.abilityOptions(A).stream().anyMatch(a->a.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,own.instanceId()))),"own Basic ability removed");var other=StarterDeck100PokemonTest.hand(m,id(7));m.playBasicPokemonToBench(A,other.instanceId());m.switchActiveByEffect(A,A,other.instanceId());check(!m.abilityOptions(B).isEmpty(),"source moved to Bench but suppression remained");m.switchActiveByEffect(A,A,source);check(m.abilityOptions(B).isEmpty(),"source returned Active but suppression absent");m.endTurn(A);TopDeckLookTest.rejects(()->m.useAbility(B,m.activePokemonView(B).pokemonId(),"mysterious-tail"));}
    static void disabled(){var m=StarterDeck100PokemonTest.game(100,171);m.disableAbilityEffectsByEffect(A,A,m.activePokemonView(A).pokemonId());check(!m.abilityOptions(B).isEmpty(),"disabled source retained suppression");}
    static void exceptions(){for(int n:List.of(16,56)){var m=StarterDeck100PokemonTest.game(n,100);var source=m.activePokemonView(A).pokemonId();check(m.abilityOptions(A).stream().anyMatch(a->a.pokemonId().equals(source)),"Emperor Eyes suppressed Evolution or Rule Box "+n);}var m=StarterDeck100PokemonTest.game(100,100);StarterDeck100PokemonTest.attack(m,0);var cards=m.effectCardPrompt(A);m.submitEffectCards(A,cards.resolutionId(),cards.step(),List.of(cards.candidates().getFirst().instanceId()));var target=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,target.resolutionId(),target.step(),target.targets().getFirst());check(m.lastAttack().finalDamage()==130,"two Rule-Box sources interfered");}
    static void transfer(){var m=StarterDeck100PokemonTest.game(100,1,id(7),id(414));var ally=StarterDeck100PokemonTest.hand(m,id(7));m.playBasicPokemonToBench(A,ally.instanceId());var rapid=StarterDeck100EnergyTest.attach(m,A,A,id(414),m.activePokemonView(A).pokemonId());StarterDeck100PokemonTest.attack(m,0);var p=m.effectCardPrompt(A);TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(rapid.instanceId()));var t=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,t.resolutionId(),t.step(),PokemonIdentityTestSupport.logical(m,A,ally.instanceId()));check(m.privateView(A).discard().contains(rapid)&&m.activePokemonView(A).attachedEnergyIds().size()==3,"one unit must move whole Rapid Energy card and discard on incompatible host");}
}
